{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Acitretin, a retinoid with the same polyene backbone as the query, showed a mean absolute oral bioavailability of 72% versus intravenous infusion in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The absolute bioavailability of acitretin is approximately 60% (range 36–95%) after a single 50 mg oral dose given with food, compared with an intravenous infusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Etretinate, a lipophilic retinoid ester structurally related to the query, has an absolute bioavailability of 44 ± 14% (range 30–70%) after oral capsule administration versus i.v. dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, the 13-cis retinoic acid isomer sharing the query's retinoid skeleton, has a systemic bioavailability of 40% at a dosage of 1 mg/kg/day.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Retinoic acid (tretinoin) showed an absolute bioavailability of 52% in humans when comparing oral tablet AUC with intravenous administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paracetamol, which contains the same 4-hydroxyanilide moiety as the query, has an absolute oral bioavailability of 0.63 ± 0.02 versus intravenous administration in healthy volunteers.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a retinoic acid 4-hydroxyanilide. The most transferable evidence from retinoid analogues (acitretin, etretinate, isotretinoin, tretinoin) consistently shows oral bioavailability values of 40–72%, all well above the 20% threshold. The shared 4-hydroxyanilide with paracetamol also supports adequate absorption. No transferable evidence indicates F below 20%; therefore, the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact retinoic acid 4-hydroxyanilide query molecule.",
    "The effect of the anilide modification on first-pass metabolism and absorption relative to the free-acid retinoids is not directly measured.",
    "Some tretinoin records report low and erratic bioavailability in specific patient populations, but these are qualitative and context-dependent rather than absolute threshold-relevant values."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
